solution:
def is_not_prime(n):
    if n <= 1:
        return True
    if n == 2:
        return False
    if n % 2 == 0:
        return True

    divisor = 3
    while divisor * divisor <= n:
        if n % divisor == 0:
            return True
        divisor += 2

    return False

import heapq

def heap_queue_largest(numbers, n):
    if n <= 0:
        return []
    return heapq.nlargest(n, numbers)

def differ_At_One_Bit_Pos(a, b):
    xor = a ^ b
    return xor != 0 and (xor & (xor - 1)) == 0

def find_Rotations(s):
    n = len(s)
    if n == 0:
        return 0

    for k in range(1, n + 1):
        if s[k:] + s[:k] == s:
            return k

def remove_Occ(string, char):
    if not char:
        return string

    first = string.find(char)
    if first == -1:
        return string

    last = string.rfind(char)

    if first == last:
        return string[:first] + string[first + len(char):]

    result = string[:last] + string[last + len(char):]
    result = result[:first] + result[first + len(char):]
    return result

import re

def text_lowercase_underscore(text):
    return bool(re.fullmatch(r"[a-z]+_[a-z]+", text))

def remove_dirty_chars(str1, str2):
    dirty_chars = set(str2)
    return ''.join(char for char in str1 if char not in dirty_chars)

def test_duplicate(arr):
    seen = set()
    for num in arr:
        if num in seen:
            return True
        seen.add(num)
    return False

def is_woodall(n):
    if n <= 0:
        return False

    k = 1
    while True:
        value = k * (2 ** k) - 1
        if value == n:
            return True
        if value > n:
            return False
        k += 1

def check(n):
    if not isinstance(n, int) or n < 0:
        return False
    reversed_n = int(str(n)[::-1])
    return n == 2 * reversed_n - 1

def find_Max_Num(nums):
    if not nums:
        return 0
    return int(''.join(map(str, sorted(nums, reverse=True))))

def count_Substrings(s):
    count = 0
    prefix_sum = 0
    freq = {0: 1}

    for ch in s:
        prefix_sum += int(ch) - 1
        count += freq.get(prefix_sum, 0)
        freq[prefix_sum] = freq.get(prefix_sum, 0) + 1

    return count

def recursive_list_sum(data):
    total = 0
    for item in data:
        if isinstance(item, list):
            total += recursive_list_sum(item)
        else:
            total += item
    return total

def bell_number(n):
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    bell = [[0] * (n + 1) for _ in range(n + 1)]
    bell[0][0] = 1

    for i in range(1, n + 1):
        bell[i][0] = bell[i - 1][i - 1]
        for j in range(1, i + 1):
            bell[i][j] = bell[i][j - 1] + bell[i - 1][j - 1]

    return bell[n][0]

def is_Monotonic(arr):
    increasing = True
    decreasing = True

    for i in range(1, len(arr)):
        if arr[i] < arr[i - 1]:
            increasing = False
        if arr[i] > arr[i - 1]:
            decreasing = False

    return increasing or decreasing

def is_sublist(main_list, sub_list):
    if not sub_list:
        return True

    sub_len = len(sub_list)
    main_len = len(main_list)

    if sub_len > main_len:
        return False

    for i in range(main_len - sub_len + 1):
        if main_list[i:i + sub_len] == sub_list:
            return True

    return False

def get_equal(test_list):
    iterator = iter(test_list)
    try:
        first = next(iterator)
    except StopIteration:
        return True

    first_length = len(first)
    return all(len(item) == first_length for item in iterator)

def comb_sort(elements):
    gap = len(elements)
    shrink = 1.3
    swapped = True

    while gap > 1 or swapped:
        gap = int(gap / shrink)
        if gap < 1:
            gap = 1

        swapped = False
        for i in range(len(elements) - gap):
            if elements[i] > elements[i + gap]:
                elements[i], elements[i + gap] = elements[i + gap], elements[i]
                swapped = True

    return elements

def is_samepatterns(sequence, patterns):
    if len(sequence) != len(patterns):
        return False

    seq_to_pat = {}
    pat_to_seq = {}

    for item, pattern in zip(sequence, patterns):
        if item in seq_to_pat:
            if seq_to_pat[item] != pattern:
                return False
        else:
            seq_to_pat[item] = pattern

        if pattern in pat_to_seq:
            if pat_to_seq[pattern] != item:
                return False
        else:
            pat_to_seq[pattern] = item

    return True

import math

def volume_sphere(radius):
    return (4.0 / 3.0) * math.pi * (radius ** 3)

def sequence(n):
    if n <= 0:
        raise ValueError("n must be a positive integer")
    if n <= 2:
        return 1

    dp = [0] * (n + 1)
    dp[1] = 1
    dp[2] = 1

    for i in range(3, n + 1):
        prev = dp[i - 1]
        dp[i] = dp[prev] + dp[i - prev]

    return dp[n]

import math

def surfacearea_sphere(radius):
    return 4 * math.pi * radius ** 2

