def freq_count(lst):
    counts = {}
    for item in lst:
        counts[item] = counts.get(item, 0) + 1
    return counts

def len_log(words):
    max_length = 0
    for word in words:
        if len(word) > max_length:
            max_length = len(word)
    return max_length

def is_undulating(n):
    if n < 0:
        return False

    digits = str(n)

    if len(digits) < 3:
        return False

    if digits[0] == digits[1]:
        return False

    for i in range(2, len(digits)):
        if digits[i] != digits[i - 2]:
            return False

    return True

import math

def divisor(n):
    n = abs(n)
    if n == 0:
        return 0

    count = 0
    for i in range(1, math.isqrt(n) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def frequency_lists(list_of_lists):
    freq = {}
    for sublist in list_of_lists:
        for element in sublist:
            freq[element] = freq.get(element, 0) + 1
    return freq

def multiply_num(numbers):
    nums = list(numbers)
    product = 1
    for num in nums:
        product *= num
    return product / len(nums)

def decimal_to_binary(n):
    if n == 0:
        return "0"

    sign = "-" if n < 0 else ""
    n = abs(n)
    bits = []

    while n > 0:
        bits.append(str(n % 2))
        n //= 2

    return sign + "".join(reversed(bits))

def next_smallest_palindrome(n):
    target = n + 1
    s = str(target)
    length = len(s)

    def make_palindrome(left_part):
        if length % 2 == 0:
            return int(left_part + left_part[::-1])
        return int(left_part + left_part[-2::-1])

    left = s[:(length + 1) // 2]
    candidate = make_palindrome(left)

    if candidate >= target:
        return candidate

    left = str(int(left) + 1)
    return make_palindrome(left)

def kth_element(arr, k):
    if k <= 0 or k > len(arr):
        raise IndexError("k is out of range")
    return arr[k - 1]

def eulerian_num(n, m):
    if n < 0 or m < 0:
        return 0
    if n == 0 and m == 0:
        return 1
    if m >= n:
        return 0

    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        upper = min(i - 1, m)
        for j in range(upper + 1):
            left = dp[i - 1][j - 1] if j > 0 else 0
            right = dp[i - 1][j] if j <= m else 0
            dp[i][j] = (i - j) * left + (j + 1) * right

    return dp[n][m]

def odd_Equivalent(binary_string, n):
    if not binary_string or n <= 0:
        return 0

    length = len(binary_string)
    ones_per_cycle = binary_string.count("1")

    full_cycles, remainder = divmod(n, length)
    total = full_cycles * ones_per_cycle

    for i in range(remainder):
        if binary_string[i] == "1":
            total += 1

    return total

