def common_in_nested_lists(nested_lists):
    if not nested_lists:
        return []

    common = set(nested_lists[0])
    for inner_list in nested_lists[1:]:
        common &= set(inner_list)

    return list(common)

def check_integer(s):
    if not isinstance(s, str):
        return False

    s = s.strip()
    if not s:
        return False

    if s[0] in "+-":
        s = s[1:]

    return bool(s) and s.isdigit()

def search(arr):
    low, high = 0, len(arr) - 1

    while low < high:
        mid = (low + high) // 2

        if mid % 2 == 1:
            mid -= 1

        if arr[mid] == arr[mid + 1]:
            low = mid + 2
        else:
            high = mid

    return arr[low]

from math import isqrt
from functools import lru_cache

def amicable_numbers_sum(n):
    if n < 2:
        return 0

    @lru_cache(maxsize=None)
    def divisor_sum(x):
        if x <= 1:
            return 0

        total = 1
        limit = isqrt(x)

        for d in range(2, limit + 1):
            if x % d == 0:
                total += d
                other = x // d
                if other != d:
                    total += other

        return total

    total = 0

    for a in range(2, n + 1):
        b = divisor_sum(a)
        if b != a and divisor_sum(b) == a:
            total += a

    return total

import cmath

def angle_complex(x, y):
    return cmath.phase(x + y)

def find_length(s):
    if not s:
        return 0

    current = 1 if s[0] == "0" else -1
    best = current

    for ch in s[1:]:
        value = 1 if ch == "0" else -1
        current = max(value, current + value)
        best = max(best, current)

    return best

import math

def sum(a, b):
    g = math.gcd(abs(a), abs(b))
    if g == 0:
        return 0

    total = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            total += i
            if i != g // i:
                total += g // i
        i += 1

    return total

def magic_square_test(matrix):
    if not matrix:
        return False

    n = len(matrix)

    for row in matrix:
        if len(row) != n:
            return False

    target = sum(matrix[0])

    for row in matrix:
        if sum(row) != target:
            return False

    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != target:
            return False

    if sum(matrix[i][i] for i in range(n)) != target:
        return False

    if sum(matrix[i][n - 1 - i] for i in range(n)) != target:
        return False

    return True
